-- ===== Branch Pulse: load of company __CODE__ (generated by infra/export-dev-data.sh; this block runs before the data) =====
-- Run the whole file in ONE transaction, as the postgres user, after the migrations:
--   psql -U postgres -d branch_pulse -v ON_ERROR_STOP=1 --single-transaction -f data.sql
-- Re-running it replaces the company again. Other companies and the Super Admin are never touched.
SET session_replication_role = replica; -- ordering of rows does not matter while loading

-- the data was exported from a database at migration __MIGRATION__: production must be at least that far
DO $chk$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM public._prisma_migrations WHERE migration_name = '__MIGRATION__' AND finished_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Production database is behind (missing migration __MIGRATION__). git pull, rebuild (docker compose ... build) and run: docker compose ... run --rm migrate  - then load this file again';
  END IF;
END $chk$;

-- ---- helper functions (session only)
__PURGE__

-- ---- permissions and units are shared master data with different ids in each database: dev id -> code
CREATE TEMP TABLE bp_idmap (kind text, code text, dev_id uuid);
INSERT INTO bp_idmap VALUES
__MAP__;
DO $chk$ DECLARE missing text; BEGIN
  SELECT string_agg(m.kind || ':' || m.code, ', ') INTO missing FROM pg_temp.bp_idmap m
  WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE m.kind = 'permissions' AND p.code = m.code)
    AND NOT EXISTS (SELECT 1 FROM public.units u WHERE m.kind = 'units' AND u.code = m.code);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Production is missing permissions/units that dev has (the migrations differ): %', missing;
  END IF;
END $chk$;

-- ---- remove the previous copy of the company: by code, by id (a copy loaded earlier under an old code) and, if given,
--      other test companies:  psql -v also_remove="'CMP002','CMP003'" ...
SELECT pg_temp.bp_delete_company($c$code = '__CODE__' OR id = '__ID__'$c$);
\if :{?also_remove}
SELECT pg_temp.bp_delete_company(format('code IN (%s)', :'also_remove'));
\endif
SELECT pg_temp.bp_sweep();

-- ---- a user whose username / mobile is already taken gets the next free number instead of failing the load
CREATE FUNCTION public.bp_fix_user_keys() RETURNS trigger LANGUAGE plpgsql AS $f$
DECLARE
  n bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE username IN (NEW.username, NEW.mobile) OR mobile IN (NEW.username, NEW.mobile)) THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.mobile, NEW.username) !~ '^\d{10}$' THEN
    RETURN NEW; -- not a mobile-style key: let the unique index report it
  END IF;
  n := COALESCE(NEW.mobile, NEW.username)::bigint;
  LOOP
    n := n + 1;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.users WHERE username = n::text OR mobile = n::text);
  END LOOP;
  RAISE NOTICE 'user key % already in use: % now signs in as %', COALESCE(NEW.mobile, NEW.username), NEW.full_name, n;
  IF NEW.username = COALESCE(NEW.mobile, NEW.username) THEN NEW.username := n::text; END IF;
  IF NEW.mobile IS NOT NULL THEN NEW.mobile := n::text; END IF;
  RETURN NEW;
END $f$;
CREATE TRIGGER bp_fix_user_keys BEFORE INSERT ON public.users FOR EACH ROW EXECUTE FUNCTION public.bp_fix_user_keys();
ALTER TABLE public.users ENABLE ALWAYS TRIGGER bp_fix_user_keys;
